target.css:
:root {
  --tag-bg: #f2e8d5;
  --tag-border: #b5915a;
  --header-bg: #7a4f2e;
  --header-text: #f5edd8;
  --label-color: #9b6f3e;
  --piece-name-color: #3b2410;
  --wood-type-color: #5c3d1e;
  --footer-bg: #e0cba8;
  --footer-text: #7a4f2e;
  --tag-number-color: #d4a96a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
}

.carving-tag {
  background-color: var(--tag-bg);
  border: 2px solid var(--tag-border);
  border-radius: 6px;
  width: 260px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
}

.studio-name {
  color: var(--header-text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.tag-number {
  color: var(--tag-number-color);
  font-size: 12px;
  font-weight: 600;
}

.tag-body {
  padding: 16px 14px 12px;
}

.piece-label,
.wood-label {
  color: var(--label-color);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  margin: 0 0 2px;
}

.piece-name {
  color: var(--piece-name-color);
  font-size: 22px;
  font-weight: 700;
  margin: 0 0 12px;
  line-height: 1.1;
}

.wood-type {
  color: var(--wood-type-color);
  font-size: 13px;
  font-weight: 400;
  margin: 0;
}

.tag-footer {
  background-color: var(--footer-bg);
  padding: 8px 14px;
  border-top: 1px solid var(--tag-border);
  text-align: center;
}

.status {
  color: var(--footer-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

